const express = require('express');
const cors = require('cors');
const { Kafka } = require('kafkajs');

const app = express();
app.use(cors());
app.use(express.json());

// Kafka client configuration
const kafka = new Kafka({
  clientId: 'ingestion-api',
  brokers: ['127.0.0.1:9092'],
  retry: {
    retries: 3,
    initialRetryTime: 100,
  }
});

const producer = kafka.producer({
  maxInFlightRequests: 1,
  idempotent: false,
  transactionTimeout: 30000
});

let producerReady = false;

// Initialize Kafka producer
async function initProducer() {
  try {
    await producer.connect();
    producerReady = true;
    console.log('Kafka producer connected successfully');
  } catch (error) {
    console.error('Failed to connect Kafka producer:', error);
    process.exit(1);
  }
}

// Validate event structure
function validateEvent(event) {
  const required = ['event_id', 'event_ts', 'user_id', 'product_id', 'event_type'];

  for (const field of required) {
    if (!event[field]) {
      return `Missing required field: ${field}`;
    }
  }

  if (!['view', 'cart', 'purchase'].includes(event.event_type)) {
    return 'Invalid event_type. Must be: view, cart, or purchase';
  }

  return null;
}

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({
    status: 'healthy',
    kafka_producer: producerReady ? 'connected' : 'disconnected',
    timestamp: new Date().toISOString()
  });
});

// Event ingestion endpoint
app.post('/events', async (req, res) => {
  const startTime = Date.now();

  try {
    const event = req.body;

    // Validate event
    const validation = validateEvent(event);
    if (validation) {
      return res.status(400).json({ error: validation });
    }

    if (!producerReady) {
      return res.status(503).json({ error: 'Service unavailable - Kafka producer not ready' });
    }

    // Extract price from properties if it's a purchase event
    let price = 0;
    let page = '';
    if (event.properties) {
      if (typeof event.properties === 'string') {
        try {
          const props = JSON.parse(event.properties);
          price = props.price || 0;
          page = props.page || '';
        } catch (e) {
          // Ignore parsing errors
        }
      } else if (typeof event.properties === 'object') {
        price = event.properties.price || 0;
        page = event.properties.page || '';
      }
    }

    // Prepare message for Kafka
    const enrichedEvent = {
      ...event,
      price: price,
      page: page,
      ingested_at: new Date().toISOString()
    };

    // Send to Kafka
    await producer.send({
      topic: 'analytics-events',
      messages: [{
        key: event.event_id,
        value: JSON.stringify(enrichedEvent),
        timestamp: Date.now()
      }]
    });

    const responseTime = Date.now() - startTime;

    res.json({
      success: true,
      event_id: event.event_id,
      response_time_ms: responseTime
    });

  } catch (error) {
    console.error('Error processing event:', error);
    const responseTime = Date.now() - startTime;

    res.status(500).json({
      error: 'Internal server error',
      response_time_ms: responseTime
    });
  }
});

// Batch event ingestion endpoint
app.post('/events/batch', async (req, res) => {
  const startTime = Date.now();

  try {
    const events = req.body.events || [];

    if (!Array.isArray(events)) {
      return res.status(400).json({ error: 'Expected events array' });
    }

    if (events.length === 0) {
      return res.status(400).json({ error: 'No events provided' });
    }

    if (!producerReady) {
      return res.status(503).json({ error: 'Service unavailable - Kafka producer not ready' });
    }

    // Validate all events
    const validationErrors = [];
    const validEvents = [];

    for (let i = 0; i < events.length; i++) {
      const event = events[i];
      const validation = validateEvent(event);

      if (validation) {
        validationErrors.push({ index: i, error: validation });
      } else {
        // Extract price and page from properties
        let price = 0;
        let page = '';
        if (event.properties) {
          if (typeof event.properties === 'string') {
            try {
              const props = JSON.parse(event.properties);
              price = props.price || 0;
              page = props.page || '';
            } catch (e) {
              // Ignore parsing errors
            }
          } else if (typeof event.properties === 'object') {
            price = event.properties.price || 0;
            page = event.properties.page || '';
          }
        }

        validEvents.push({
          ...event,
          price: price,
          page: page,
          ingested_at: new Date().toISOString()
        });
      }
    }

    if (validationErrors.length > 0) {
      return res.status(400).json({
        error: 'Validation failed',
        details: validationErrors
      });
    }

    // Send all valid events to Kafka
    const messages = validEvents.map(event => ({
      key: event.event_id,
      value: JSON.stringify(event),
      timestamp: Date.now()
    }));

    await producer.send({
      topic: 'analytics-events',
      messages: messages
    });

    const responseTime = Date.now() - startTime;

    res.json({
      success: true,
      events_processed: validEvents.length,
      response_time_ms: responseTime
    });

  } catch (error) {
    console.error('Error processing batch events:', error);
    const responseTime = Date.now() - startTime;

    res.status(500).json({
      error: 'Internal server error',
      response_time_ms: responseTime
    });
  }
});

const PORT = process.env.PORT || 3000;

// Start server
async function start() {
  await initProducer();

  app.listen(PORT, '0.0.0.0', () => {
    console.log(`Analytics ingestion API listening on port ${PORT}`);
    console.log(`Health check: http://localhost:${PORT}/health`);
    console.log(`Event ingestion: POST http://localhost:${PORT}/events`);
    console.log(`Batch ingestion: POST http://localhost:${PORT}/events/batch`);
  });
}

// Graceful shutdown
process.on('SIGTERM', async () => {
  console.log('Shutting down...');
  await producer.disconnect();
  process.exit(0);
});

process.on('SIGINT', async () => {
  console.log('Shutting down...');
  await producer.disconnect();
  process.exit(0);
});

start().catch(console.error);

