const { Kafka } = require('kafkajs');
const { createClient } = require('@clickhouse/client');

// ClickHouse client
const clickhouse = createClient({
  host: 'http://localhost:8123',
  database: 'analytics',
  clickhouse_settings: {
    async_insert: 1,
    wait_for_async_insert: 0,
    async_insert_max_data_size: 1000000,
    async_insert_busy_timeout_ms: 200
  }
});

// Kafka client
const kafka = new Kafka({
  clientId: 'clickhouse-consumer',
  brokers: ['127.0.0.1:9092'],
  retry: {
    retries: 5,
    initialRetryTime: 300,
  }
});

const consumer = kafka.consumer({
  groupId: 'clickhouse-analytics-group',
  sessionTimeout: 30000,
  rebalanceTimeout: 60000,
  heartbeatInterval: 3000,
  maxBytesPerPartition: 1048576,
  maxBytes: 5242880
});

let messageCount = 0;
let errorCount = 0;

async function initConsumer() {
  try {
    await consumer.connect();
    console.log('Kafka consumer connected successfully');

    await consumer.subscribe({ topic: 'analytics-events', fromBeginning: true });
    console.log('Subscribed to analytics-events topic');

    // Test ClickHouse connection
    await clickhouse.ping();
    console.log('ClickHouse connection successful');

  } catch (error) {
    console.error('Failed to initialize consumer:', error);
    process.exit(1);
  }
}

async function insertToClickHouse(events) {
  try {
    const rows = events.map(event => {
      const data = JSON.parse(event.value);
      return {
        event_id: data.event_id,
        event_ts: new Date(data.event_ts),
        user_id: data.user_id,
        product_id: data.product_id,
        event_type: data.event_type,
        properties: data.properties ? JSON.stringify(data.properties) : '{}',
        price: data.price || 0,
        page: data.page || '',
        ingested_at: new Date(data.ingested_at || new Date())
      };
    });

    await clickhouse.insert({
      table: 'events',
      values: rows,
      format: 'JSONEachRow'
    });

    messageCount += events.length;
    console.log(`Inserted ${events.length} events to ClickHouse. Total: ${messageCount}`);
    return true;

  } catch (error) {
    console.error('Failed to insert to ClickHouse:', error);
    errorCount += events.length;
    return false;
  }
}

async function processMessages() {
  try {
    await consumer.run({
