const express = require('express');
const cors = require('cors');
const { createClient } = require('@clickhouse/client');

const app = express();
app.use(cors());
app.use(express.json());

// ClickHouse client with optimized settings for read queries
const clickhouse = createClient({
  host: 'http://localhost:8123',
  database: 'analytics',
  clickhouse_settings: {
    // Optimize for read performance
    use_uncompressed_cache: 1,
    compile_expressions: 1,
    min_count_to_compile_expression: 0,
    max_threads: 4
  }
});

// Health check endpoint
app.get('/health', async (req, res) => {
  const startTime = Date.now();

  try {
    await clickhouse.ping();
    const responseTime = Date.now() - startTime;

    res.json({
      status: 'healthy',
      clickhouse: 'connected',
      response_time_ms: responseTime,
      timestamp: new Date().toISOString()
    });
  } catch (error) {
    const responseTime = Date.now() - startTime;

    res.status(503).json({
      status: 'unhealthy',
      clickhouse: 'disconnected',
      error: error.message,
      response_time_ms: responseTime,
      timestamp: new Date().toISOString()
    });
  }
});

// Top products endpoint
app.get('/analytics/top-products', async (req, res) => {
  const startTime = Date.now();

  try {
    const limit = Math.min(parseInt(req.query.limit) || 10, 100);
    const sortBy = req.query.sort_by || 'views'; // 'views', 'purchases', 'revenue'

    let orderBy = 'views DESC';
    if (sortBy === 'purchases') orderBy = 'purchases DESC';
    if (sortBy === 'revenue') orderBy = 'revenue DESC';

    const query = `
      SELECT
        product_id,
        sum(views) as views,
        sum(cart_adds) as cart_adds,
        sum(purchases) as purchases,
        sum(revenue) as revenue,
        round(sum(purchases) / sum(views) * 100, 2) as conversion_rate,
        round(sum(revenue) / sum(purchases), 2) as avg_order_value
      FROM analytics.product_metrics
      WHERE date >= today() - 7  -- Last 7 days
      GROUP BY product_id
      ORDER BY ${orderBy}
      LIMIT ${limit}
    `;

    const result = await clickhouse.query({
      query: query,
      format: 'JSONEachRow'
    });

    const data = await result.json();
    const responseTime = Date.now() - startTime;

    res.json({
      success: true,
      data: data,
      metadata: {
        total_products: data.length,
        sort_by: sortBy,
        limit: limit,
        period: 'last_7_days'
      },
      response_time_ms: responseTime
    });

  } catch (error) {
    console.error('Top products query error:', error);
    const responseTime = Date.now() - startTime;

    res.status(500).json({
      success: false,
      error: 'Internal server error',
      response_time_ms: responseTime
    });
  }
});

// Conversion funnel endpoint
app.get('/analytics/conversion-funnel', async (req, res) => {
  const startTime = Date.now();

  try {
    const query = `
      WITH funnel_stats AS (
        SELECT
          uniq(user_id) as total_users,
          uniqIf(user_id, event_type = 'view') as users_viewed,
          uniqIf(user_id, event_type = 'cart') as users_cart,
          uniqIf(user_id, event_type = 'purchase') as users_purchased,
          countIf(event_type = 'view') as total_views,
          countIf(event_type = 'cart') as total_cart_adds,
          countIf(event_type = 'purchase') as total_purchases,
          sum(price) as total_revenue
        FROM analytics.events
        WHERE event_ts >= now() - INTERVAL 7 DAY
      )
      SELECT
        total_users,
        users_viewed,
        users_cart,
        users_purchased,
        total_views,
        total_cart_adds,
        total_purchases,
        total_revenue,
        round(users_cart / users_viewed * 100, 2) as view_to_cart_rate,
        round(users_purchased / users_cart * 100, 2) as cart_to_purchase_rate,
        round(users_purchased / users_viewed * 100, 2) as view_to_purchase_rate,
        round(total_revenue / users_purchased, 2) as avg_revenue_per_user
      FROM funnel_stats
    `;

    const result = await clickhouse.query({
      query: query,
      format: 'JSONEachRow'
    });

    const data = await result.json();
    const responseTime = Date.now() - startTime;

    // Format the response with funnel steps
    const stats = data[0] || {};

    const funnelSteps = [
      {
        step: 'view',
        users: parseInt(stats.users_viewed || 0),
        events: parseInt(stats.total_views || 0),
        conversion_rate: 100.0
      },
      {
        step: 'cart',
        users: parseInt(stats.users_cart || 0),
        events: parseInt(stats.total_cart_adds || 0),
        conversion_rate: parseFloat(stats.view_to_cart_rate || 0)
      },
      {
        step: 'purchase',
        users: parseInt(stats.users_purchased || 0),
        events: parseInt(stats.total_purchases || 0),
        conversion_rate: parseFloat(stats.view_to_purchase_rate || 0)
      }
    ];

    res.json({
      success: true,
      data: {
        funnel_steps: funnelSteps,
        summary: {
          total_users: parseInt(stats.total_users || 0),
          total_revenue: parseFloat(stats.total_revenue || 0),
          avg_revenue_per_user: parseFloat(stats.avg_revenue_per_user || 0),
          overall_conversion_rate: parseFloat(stats.view_to_purchase_rate || 0)
        }
      },
      metadata: {
        period: 'last_7_days',
        currency: 'USD'
      },
      response_time_ms: responseTime
    });

  } catch (error) {
    console.error('Conversion funnel query error:', error);
    const responseTime = Date.now() - startTime;

    res.status(500).json({
      success: false,
      error: 'Internal server error',
      response_time_ms: responseTime
    });
  }
});

// Hourly activity endpoint
app.get('/analytics/hourly-activity', async (req, res) => {
  const startTime = Date.now();

  try {
    const days = Math.min(parseInt(req.query.days) || 1, 7);

    const query = `
      SELECT
        date,
        hour,
        sum(total_events) as events,
        sum(unique_users) as unique_users,
        sum(total_revenue) as revenue,
        formatDateTime(toDateTime(date + toIntervalHour(hour)), '%Y-%m-%d %H:00:00') as timestamp
      FROM analytics.hourly_activity
      WHERE date >= today() - ${days}
      GROUP BY date, hour
      ORDER BY date DESC, hour DESC
      LIMIT 168  -- Max 7 days * 24 hours
    `;

    const result = await clickhouse.query({
      query: query,
      format: 'JSONEachRow'
    });

    const data = await result.json();
    const responseTime = Date.now() - startTime;

    // Calculate summary statistics
    const summary = data.reduce((acc, row) => {
      acc.total_events += parseInt(row.events || 0);
      acc.total_revenue += parseFloat(row.revenue || 0);
      acc.peak_events = Math.max(acc.peak_events, parseInt(row.events || 0));
      acc.peak_users = Math.max(acc.peak_users, parseInt(row.unique_users || 0));
      return acc;
    }, {
      total_events: 0,
      total_revenue: 0,
      peak_events: 0,
      peak_users: 0
    });

    res.json({
      success: true,
      data: {
        hourly_data: data,
        summary: {
          ...summary,
          avg_events_per_hour: data.length > 0 ? Math.round(summary.total_events / data.length) : 0,
          avg_revenue_per_hour: data.length > 0 ? Math.round(summary.total_revenue / data.length * 100) / 100 : 0
        }
      },
      metadata: {
        period_days: days,
        data_points: data.length,
        currency: 'USD'
      },
      response_time_ms: responseTime
    });

  } catch (error) {
    console.error('Hourly activity query error:', error);
    const responseTime = Date.now() - startTime;

    res.status(500).json({
      success: false,
      error: 'Internal server error',
      response_time_ms: responseTime
    });
  }
});

// Event counts endpoint (for debugging)
app.get('/analytics/debug/counts', async (req, res) => {
  const startTime = Date.now();

  try {
    const query = `
      SELECT
        count() as total_events,
        countIf(event_type = 'view') as views,
        countIf(event_type = 'cart') as cart_adds,
        countIf(event_type = 'purchase') as purchases,
        uniq(user_id) as unique_users,
        uniq(product_id) as unique_products,
        min(event_ts) as earliest_event,
        max(event_ts) as latest_event
      FROM analytics.events
    `;

    const result = await clickhouse.query({
      query: query,
      format: 'JSONEachRow'
    });

    const data = await result.json();
    const responseTime = Date.now() - startTime;

    res.json({
      success: true,
      data: data[0] || {},
      response_time_ms: responseTime
    });

  } catch (error) {
    console.error('Debug counts query error:', error);
    const responseTime = Date.now() - startTime;

    res.status(500).json({
      success: false,
      error: 'Internal server error',
      response_time_ms: responseTime
    });
  }
});

const PORT = process.env.PORT || 3001;

// Start server
async function start() {
  try {
    // Test ClickHouse connection
    await clickhouse.ping();
    console.log('ClickHouse connection successful');

    app.listen(PORT, '0.0.0.0', () => {
      console.log(`Analytics egress API listening on port ${PORT}`);
      console.log(`Health check: http://localhost:${PORT}/health`);
      console.log(`Top products: http://localhost:${PORT}/analytics/top-products`);
      console.log(`Conversion funnel: http://localhost:${PORT}/analytics/conversion-funnel`);
      console.log(`Hourly activity: http://localhost:${PORT}/analytics/hourly-activity`);
      console.log(`Debug counts: http://localhost:${PORT}/analytics/debug/counts`);
    });

  } catch (error) {
    console.error('Failed to start egress API:', error);
    process.exit(1);
  }
}

// Graceful shutdown
process.on('SIGTERM', async () => {
  console.log('Shutting down...');
  await clickhouse.close();
  process.exit(0);
});

process.on('SIGINT', async () => {
  console.log('Shutting down...');
  await clickhouse.close();
  process.exit(0);
});

start().catch(console.error);

