    const responseTime = Date.now() - startTime;

    res.json({
      success: true,
      data: data[0] || {},
      response_time_ms: responseTime
    });

  } catch (error) {
    console.error('Debug counts query error:', error);
    const responseTime = Date.now() - startTime;

    res.status(500).json({
      success: false,
      error: 'Internal server error',
      response_time_ms: responseTime
    });
  }
});

const PORT = process.env.PORT || 3001;

// Start server
async function start() {
  try {
    // Test ClickHouse connection
    await clickhouse.ping();
    console.log('ClickHouse connection successful');

    app.listen(PORT, '0.0.0.0', () => {
      console.log(`Analytics egress API listening on port ${PORT}`);
      console.log(`Health check: http://localhost:${PORT}/health`);
      console.log(`Top products: http://localhost:${PORT}/analytics/top-products`);
      console.log(`Conversion funnel: http://localhost:${PORT}/analytics/conversion-funnel`);
      console.log(`Hourly activity: http://localhost:${PORT}/analytics/hourly-activity`);
      console.log(`Debug counts: http://localhost:${PORT}/analytics/debug/counts`);
    });

  } catch (error) {
    console.error('Failed to start egress API:', error);
    process.exit(1);
  }
}

// Graceful shutdown
process.on('SIGTERM', async () => {
  console.log('Shutting down...');
  await clickhouse.close();
  process.exit(0);
});

process.on('SIGINT', async () => {
  console.log('Shutting down...');
  await clickhouse.close();
  process.exit(0);
});

start().catch(console.error);

