const fs = require('fs');
const path = require('path');

// Read all event files from /data/events/
async function loadSeedEvents() {
  try {
    const eventsDir = '/data/events';
    const files = fs.readdirSync(eventsDir).filter(file => file.endsWith('.json'));

    console.log(`Found ${files.length} event files to process`);

    const events = [];

    // Read and parse each event file
    for (const file of files) {
      const filePath = path.join(eventsDir, file);
      const content = fs.readFileSync(filePath, 'utf8').trim();

      try {
        const event = JSON.parse(content);
        events.push(event);
        console.log(`Loaded event: ${event.event_id}`);
      } catch (parseError) {
        console.error(`Failed to parse ${file}:`, parseError.message);
      }
    }

    if (events.length === 0) {
      console.error('No valid events found');
      return;
    }

    console.log(`\nPreparing to send ${events.length} events to ingestion API...`);

    // Send events to ingestion API using batch endpoint
    const response = await fetch('http://localhost:3000/events/batch', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({ events: events })
    });

    const result = await response.json();

    if (response.ok) {
      console.log('\n✅ Successfully loaded seed events!');
      console.log(`Events processed: ${result.events_processed}`);
      console.log(`Response time: ${result.response_time_ms}ms`);

      // Wait a moment for events to be processed by consumer
      console.log('\nWaiting for events to be processed by ClickHouse consumer...');
      await new Promise(resolve => setTimeout(resolve, 3000));

      // Check the debug endpoint to verify events were stored
      const debugResponse = await fetch('http://localhost:3001/analytics/debug/counts');
      const debugResult = await debugResponse.json();

      console.log('\n📊 Event storage verification:');
      console.log(`Total events in ClickHouse: ${debugResult.data?.total_events || 0}`);
      console.log(`Views: ${debugResult.data?.views || 0}`);
      console.log(`Cart adds: ${debugResult.data?.cart_adds || 0}`);
      console.log(`Purchases: ${debugResult.data?.purchases || 0}`);
      console.log(`Unique users: ${debugResult.data?.unique_users || 0}`);
      console.log(`Unique products: ${debugResult.data?.unique_products || 0}`);

    } else {
      console.error('❌ Failed to load seed events:', result);
    }

  } catch (error) {
    console.error('❌ Error loading seed events:', error);
  }
}

loadSeedEvents();

