const { Kafka } = require('kafkajs');
const { createClient } = require('@clickhouse/client');

// ClickHouse client
const clickhouse = createClient({
  host: 'http://localhost:8123',
  database: 'analytics'
});

// Kafka client
const kafka = new Kafka({
  clientId: 'simple-consumer',
  brokers: ['127.0.0.1:9092']
});

const consumer = kafka.consumer({
  groupId: 'simple-clickhouse-group'
});

let messageCount = 0;

async function processEvent(message) {
  try {
    const data = JSON.parse(message.value);
    console.log(`Processing event: ${data.event_id}`);

    const row = {
      event_id: data.event_id,
      event_ts: new Date(data.event_ts),
      user_id: data.user_id,
      product_id: data.product_id,
      event_type: data.event_type,
      properties: data.properties ? JSON.stringify(data.properties) : '{}',
      price: data.price || 0,
      page: data.page || '',
      ingested_at: new Date(data.ingested_at || new Date())
    };

    await clickhouse.insert({
      table: 'events',
      values: [row],
      format: 'JSONEachRow'
    });

    messageCount++;
    console.log(`✅ Inserted event ${data.event_id}. Total: ${messageCount}`);
    return true;

  } catch (error) {
    console.error('❌ Failed to process event:', error);
    console.error('Message value:', message.value?.toString());
    return false;
  }
}

async function start() {
  try {
    await consumer.connect();
    console.log('✅ Connected to Kafka');

    await clickhouse.ping();
    console.log('✅ Connected to ClickHouse');

    await consumer.subscribe({ topic: 'analytics-events', fromBeginning: true });
    console.log('✅ Subscribed to analytics-events topic');

    await consumer.run({
      eachMessage: async ({ topic, partition, message }) => {
        console.log(`📨 Received message from ${topic}:${partition}:${message.offset}`);
        await processEvent(message);
      },
    });

  } catch (error) {
    console.error('❌ Consumer error:', error);
  }
}

// Graceful shutdown
process.on('SIGTERM', async () => {
  console.log(`\n🛑 Shutting down... Processed: ${messageCount}`);
  await consumer.disconnect();
  await clickhouse.close();
  process.exit(0);
});

process.on('SIGINT', async () => {
  console.log(`\n🛑 Shutting down... Processed: ${messageCount}`);
  await consumer.disconnect();
  await clickhouse.close();
  process.exit(0);
});

start();

